-- Add screenshots to Shams, NOOR and the pricing calculator.
-- Replaces those three entries only while they still have no cover image (i.e. were not edited in the dashboard).
UPDATE docs
SET value = json_set(value, '$.projects',
      (SELECT COALESCE(json_group_array(json(p.value)), json('[]'))
       FROM json_each(docs.value, '$.projects') AS p
       WHERE NOT (json_extract(p.value, '$.id') IN ('prj-shams','prj-noor','prj-pricing-calculator')
                  AND COALESCE(json_extract(p.value, '$.image'), '') = ''))),
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
WHERE key = 'content';

