SET value = json_insert(value, '$.projects[#]', json('{"status":"published","updatedAt":"2026-10-29T12:00:00.000Z","gallery":[{"src":"/images/projects/shams/cover.webp","caption":{"en":"Arabic storefront homepage (demo data)","ar":"الصفحة الرئيسية للمتجر بالعربية (بيانات تجريبية)"}},{"src":"/images/projects/shams/shop.webp","caption":{"en":"Product listing with filters","ar":"قائمة المنتجات مع الفلاتر"}},{"src":"/images/projects/shams/lens.webp","caption":{"en":"Prescription-lens configurator","ar":"مُهيّئ العدسات الطبية"}},{"src":"/images/projects/shams/admin.webp","caption":{"en":"Staff dashboard with sales and branch reports (demo data)","ar":"لوحة الموظفين مع تقارير المبيعات والفروع (بيانات تجريبية)"}},{"src":"/images/projects/shams/mobile.webp","caption":{"en":"Mobile storefront","ar":"المتجر على الموبايل"}}],"image":"/images/projects/shams/cover.webp","featured":true,"projectStatus":"completed","year":"2026","timeline":{"en":"","ar":""},"results":{"en":"","ar":""},"id":"prj-shams","order":9,"slug":"shams-optical-platform","title":{"en":"Shams — Optical Retail Platform","ar":"شمس — منصة إدارة وبيع النظارات"},"summary":{"en":"An Arabic-first commerce and operations platform for an optical chain: storefront with a prescription-lens configurator, multi-branch inventory, orders, payments, CRM, point of sale and staff permissions.","ar":"منصة تجارة وتشغيل بالعربية لسلسلة محلات بصريات: متجر مع مُهيّئ عدسات طبية، ومخزون متعدد الفروع، وطلبات ومدفوعات وCRM ونقطة بيع وصلاحيات للموظفين."},"category":"e-commerce","stack":"Next.js, React, TypeScript, Prisma, PostgreSQL, better-auth, Vitest, Playwright","liveUrl":"","githubUrl":"","role":{"en":"Full-Stack Developer","ar":"مطوّر ويب متكامل"},"client":{"en":"Personal project","ar":"مشروع شخصي"},"overview":{"en":"A full retail platform for an Egyptian optical chain, built as one Next.js and PostgreSQL modular monolith, with a right-to-left storefront and a staff dashboard.","ar":"منصة متكاملة لسلسلة بصريات مصرية، مبنية كتطبيق واحد منظّم بـ Next.js وPostgreSQL، بواجهة عربية من اليمين لليسار ولوحة تحكم للموظفين."},"challenge":{"en":"Selling prescription glasses online is not like selling ordinary products: the price depends on lens type and index, prescriptions are private, stock is spread across branches and money must be tracked exactly.","ar":"بيع النظارات الطبية أونلاين مختلف عن بيع المنتجات العادية: السعر يتوقف على نوع العدسة ومعامل الانكسار، والروشتات خاصة، والمخزون موزع على فروع، والأموال لازم تُتتبع بدقة."},"solution":{"en":"A server-authoritative lens configurator with a type-by-index price matrix, branch-scoped inventory with append-only movement ledgers, integer-piaster money handling, role-based permissions enforced in services, and a background job queue on PostgreSQL. Card and wallet payments run through a sandbox gateway that uses the same signed-webhook path as the real provider.","ar":"مُهيّئ عدسات تحسب الأسعار على الخادم بمصفوفة نوع × معامل انكسار، ومخزون مرتبط بالفرع بسجلات حركة لا تُعدَّل، وحساب الأموال بالقروش كأعداد صحيحة، وصلاحيات أدوار تُطبَّق في الخدمات، وطابور مهام خلفية على PostgreSQL. المدفوعات بالبطاقة والمحفظة تعمل عبر بوابة تجريبية بنفس مسار الـ webhook الموقّع للمزوّد الحقيقي."},"features":{"en":"Arabic RTL storefront with search, filters and compare\nPrescription-lens configurator\nPrivate prescriptions with a verification step\nMulti-branch inventory\nOrders, payments, returns, promotions and loyalty\nCRM, purchasing and point of sale\nRole-based staff permissions and an audit log\nBackground jobs and a system health page\nAutomated unit and end-to-end tests","ar":"متجر عربي من اليمين لليسار مع بحث وفلاتر ومقارنة\nمُهيّئ عدسات طبية\nروشتات خاصة مع خطوة تحقق\nمخزون متعدد الفروع\nطلبات ومدفوعات ومرتجعات وعروض وولاء\nإدارة علاقات العملاء والمشتريات ونقطة بيع\nصلاحيات موظفين حسب الدور وسجل مراجعة\nمهام خلفية وصفحة لحالة النظام\nاختبارات وحدة واختبارات شاملة آلية"},"responsibilities":{"en":"Architecture and database design\nBackend services and permissions\nStorefront and dashboard\nPayments integration design\nTesting and CI","ar":"هيكلة النظام وتصميم قاعدة البيانات\nالخدمات الخلفية والصلاحيات\nالمتجر ولوحة التحكم\nتصميم تكامل المدفوعات\nالاختبارات وCI"}}')),
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
