UPDATE docs
SET value = json_insert(value, '$.projects[#]', json('{"status":"published","updatedAt":"2026-10-29T12:00:00.000Z","gallery":[{"src":"/images/projects/noor/cover.webp","caption":{"en":"Home screen with daily summary (sample data)","ar":"الشاشة الرئيسية مع ملخص اليوم (بيانات تجريبية)"}},{"src":"/images/projects/noor/projects.webp","caption":{"en":"Projects list (sample data)","ar":"قائمة المشاريع (بيانات تجريبية)"}},{"src":"/images/projects/noor/tasks.webp","caption":{"en":"Tasks with priorities and due dates (sample data)","ar":"المهام بالأولويات والمواعيد (بيانات تجريبية)"}}],"image":"/images/projects/noor/cover.webp","featured":false,"projectStatus":"in-progress","year":"2026","timeline":{"en":"","ar":""},"results":{"en":"","ar":""},"id":"prj-noor","order":10,"slug":"noor-business-os","title":{"en":"NOOR — Personal Business OS","ar":"نور — نظام تشغيل شخصي للأعمال"},"summary":{"en":"An Arabic-first, local-first desktop app that keeps clients, leads, projects, tasks and a calendar on the user''s own machine, with an AI manager and voice commands that run fully offline.","ar":"تطبيق مكتبي بالعربية يعمل محليًا أولًا، يحفظ العملاء والفرص والمشاريع والمهام والتقويم على جهاز المستخدم، مع مدير بالذكاء الاصطناعي وأوامر صوتية تعمل بالكامل دون إنترنت."},"category":"web-apps","stack":"Tauri, React, TypeScript, FastAPI, SQLAlchemy, SQLite, llama.cpp, faster-whisper","liveUrl":"","githubUrl":"","role":{"en":"Full-Stack Developer","ar":"مطوّر ويب متكامل"},"client":{"en":"Personal project","ar":"مشروع شخصي"},"overview":{"en":"NOOR keeps a person''s business data on their own computer and adds an assistant that can read it, answer questions and act on it, without sending anything to the internet.","ar":"نور يحتفظ ببيانات العمل على جهاز المستخدم نفسه، ويضيف مساعدًا يقرأها ويجيب ويتصرف فيها، دون إرسال أي شيء للإنترنت."},"challenge":{"en":"Give an AI assistant useful access to private business data while keeping everything local, auditable and safe.","ar":"إعطاء مساعد ذكي وصولًا مفيدًا لبيانات عمل خاصة مع إبقاء كل شيء محليًا وقابلًا للمراجعة وآمنًا."},"solution":{"en":"A Tauri desktop shell around a React interface and a FastAPI service on SQLite. A local llama.cpp model and on-device speech recognition power the assistant, which reaches data only through a tool layer that logs every call and asks for confirmation before sensitive actions. Pluggable connectors bring in Gmail, Google Calendar and Telegram.","ar":"واجهة React داخل تطبيق Tauri وخدمة FastAPI على SQLite. نموذج llama.cpp محلي وتعرّف على الكلام على الجهاز يشغّلان المساعد، الذي لا يصل للبيانات إلا عبر طبقة أدوات تسجّل كل استدعاء وتطلب التأكيد قبل الإجراءات الحساسة. موصّلات قابلة للتركيب تجلب Gmail وGoogle Calendar وTelegram."},"features":{"en":"Arabic-first interface with light and dark themes\nClients, leads, projects, tasks and calendar in one place\nMorning summary and analytics\nFully local AI manager and voice input\nAudit log of every assistant action and confirmation for sensitive actions\nConnectors for Gmail, Google Calendar and Telegram\nEncrypted secrets","ar":"واجهة عربية أولًا بمظهر فاتح وداكن\nالعملاء والفرص والمشاريع والمهام والتقويم في مكان واحد\nملخص صباحي وتحليلات\nمدير ذكاء اصطناعي وإدخال صوتي محليان بالكامل\nسجل مراجعة لكل إجراء للمساعد وتأكيد للإجراءات الحساسة\nموصّلات لـ Gmail وGoogle Calendar وTelegram\nتشفير للأسرار"},"responsibilities":{"en":"Desktop app and UI\nBackend API and data layer\nLocal AI and voice integration\nSecurity and audit design","ar":"التطبيق المكتبي والواجهة\nالواجهة الخلفية وطبقة البيانات\nتكامل الذكاء الاصطناعي والصوت المحلي\nتصميم الأمان والمراجعة"}}')),
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
