       OR json_extract(json_each.value, '$.slug') = 'noor-business-os'
  );

UPDATE docs
SET value = json_insert(value, '$.projects[#]', json('{"status":"published","updatedAt":"2026-10-29T12:00:00.000Z","gallery":[{"src":"/images/projects/calculator/cover.webp","caption":{"en":"Packages and total","ar":"الباقات والإجمالي"}},{"src":"/images/projects/calculator/plan.webp","caption":{"en":"Pricing and payment plan","ar":"السعر وخطة الدفع"}},{"src":"/images/projects/calculator/mobile.webp","caption":{"en":"Mobile view in Arabic","ar":"الموبايل بالعربية"}},{"src":"/images/projects/calculator/english.webp","caption":{"en":"Mobile view in English","ar":"الموبايل بالإنجليزية"}}],"image":"/images/projects/calculator/cover.webp","featured":false,"projectStatus":"completed","year":"2026","timeline":{"en":"","ar":""},"results":{"en":"","ar":""},"id":"prj-pricing-calculator","order":11,"slug":"pricing-calculator","title":{"en":"Project Pricing Calculator","ar":"حاسبة تسعير المشاريع"},"summary":{"en":"A bilingual quoting tool: pick a package, add extras and quantities, apply a discount, and get the total with a staged payment plan and paid/unpaid tracking.","ar":"أداة تسعير بالعربية والإنجليزية: اختر الباقة وأضف الإضافات والكميات وطبّق خصمًا لتحصل على الإجمالي وخطة دفع على مراحل مع متابعة المدفوع."},"category":"web-apps","stack":"HTML, CSS, JavaScript, Cloudflare Workers","liveUrl":"","githubUrl":"","role":{"en":"Developer","ar":"مطوّر"},"client":{"en":"Personal project","ar":"مشروع شخصي"},"overview":{"en":"A small tool I built to quote web projects quickly and consistently, usable from a phone during a client conversation.","ar":"أداة صغيرة بنيتها لتسعير مشاريع الويب بسرعة وثبات، ويمكن استخدامها من الموبايل أثناء الحديث مع العميل."},"challenge":{"en":"Quotes were slow to put together and easy to get wrong: packages, extras, discounts and installments all had to be added up by hand.","ar":"كان إعداد عروض الأسعار بطيئًا وعرضة للخطأ: الباقات والإضافات والخصومات والدفعات كلها كانت تُجمع يدويًا."},"solution":{"en":"A dependency-free single page with a right-to-left layout and a language toggle. Three packages and optional add-ons feed one total, the payment plan splits it into stages and tracks what has been received, and a settings panel and currency selector adapt it to different clients. Deployed as static assets on Cloudflare Workers.","ar":"صفحة واحدة بدون مكتبات خارجية بتخطيط من اليمين لليسار وتبديل للغة. ثلاث باقات وإضافات اختيارية تغذي إجماليًا واحدًا، وخطة الدفع تقسّمه لمراحل وتتابع المستلم، مع لوحة إعدادات واختيار للعملة لتناسب كل عميل. منشورة كملفات ثابتة على Cloudflare Workers."},"features":{"en":"Three packages and optional add-ons with quantities\nDiscount percentage\nStaged payment plan with received / not received tracking\nCurrency selector and settings panel\nArabic and English\nMobile-first layout","ar":"ثلاث باقات وإضافات اختيارية بكميات\nنسبة خصم\nخطة دفع على مراحل مع متابعة المستلم وغير المستلم\nاختيار العملة ولوحة إعدادات\nعربي وإنجليزي\nتصميم للموبايل أولًا"},"responsibilities":{"en":"Design and implementation\nDeployment","ar":"التصميم والتنفيذ\nالنشر"}}')),
